<set-variable name="aifinops-request" value="@{
    try {
        if (context.Request.Method != "POST"
            || !context.Request.Headers.GetValueOrDefault("Content-Type", "").Contains("json")) { return ""; }
        var b = context.Request.Body.As(preserveContent: true);
        var o = new JObject();
        if (b["service_tier"] != null) { o["requestedTier"] = b["service_tier"]; }
        if (b["inference_geo"] != null) { o["requestedGeo"] = b["inference_geo"]; }
        if (b["speed"] != null) { o["requestedSpeed"] = b["speed"]; }
        var stream = b["stream"] != null && b["stream"].Type == JTokenType.Boolean && (bool)b["stream"];
        var options = b["stream_options"] as JObject;
        var includeUsage = options?["include_usage"] != null && (bool)options["include_usage"];
        if (stream && !includeUsage && context.Request.Url.Path.EndsWith("/chat/completions")) { o["streamUsage"] = "missing"; }
        return o.Count == 0 ? "" : o.ToString(Newtonsoft.Json.Formatting.None);
    } catch { return ""; }
}" />



            @((string)context.Variables["aifinops-request"])
